func telegramTimeoutFinishLocalDB(t *testing.T) gdb.DB {
	t.Helper()
	db := telegramOutboxRetryLocalDB(t) // opt-in loopback 127.0.0.1:35432 only
	ctx := context.Background()
	for _, query := range []string{
		"ALTER TABLE " + publishTgOutboxTable + " ADD COLUMN dedupe_key text UNIQUE, ADD COLUMN created_at timestamp",
		"ALTER TABLE " + publishTgOutboxTable + " ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 1000)",
		"ALTER TABLE " + publishTgOutboxTable + " ALTER COLUMN attempt_count SET DEFAULT 0",
		`CREATE TABLE ` + publishTgJobTable + ` (
			id bigint PRIMARY KEY,tenant_id bigint,account_id bigint,profile_id bigint,channel_id bigint,
			operation_no text,status text,send_phase text DEFAULT '',dispatch_status text DEFAULT 'idle',
			timeout_parent_job_id bigint DEFAULT 0,timeout_cleanup_at timestamp,
			next_retry_at timestamp,error_message text DEFAULT '',updated_at timestamp)`,
		`CREATE UNIQUE INDEX uk_ybp_tg_job_active_profile_channel ON ` + publishTgJobTable + `
			(profile_id,channel_id) WHERE status IN ('pending','sending','failed_retry','unknown')`,
		"CREATE TABLE " + publishProfileStateTable + " (tenant_id bigint,account_id bigint,profile_id bigint,publish_operation_no text,publish_task_status text,deleted_at timestamp)",
		"CREATE TABLE " + publishProfileCancelTable + " (tenant_id bigint,account_id bigint,profile_id bigint,operation_no text)",
		"CREATE TABLE " + profileDeleteIntentTable + " (tenant_id bigint,profile_id bigint)",
		"CREATE TABLE hg_content_profile (id bigint PRIMARY KEY,status integer,visibility text,deleted_at timestamp)",
		"CREATE TABLE " + publishChannelTable + " (id bigint PRIMARY KEY,tenant_id bigint,status integer,deleted_at timestamp)",
		"CREATE TABLE " + publishTgMessageTable + " (job_id bigint,status text,tg_message_id bigint)",
		"CREATE TABLE " + publishTgAttemptTable + " (id bigint,job_id bigint,status text,response_received integer,confirmed_count integer,error_message text)",
		"CREATE TABLE " + publishTgAttemptMessageTable + " (attempt_id bigint,message_id bigint)",
	} {
		if _, err := db.Exec(ctx, query); err != nil {
			t.Fatal(err)
		}
	}
	return db
}

func telegramTimeoutFinishSeed(t *testing.T, db gdb.DB) telegramJobRecord {
	t.Helper()
	ctx := context.Background()
	for _, query := range []string{
		"INSERT INTO " + publishTgJobTable + ` (id,tenant_id,account_id,profile_id,channel_id,operation_no,status,send_phase,timeout_cleanup_at)
			VALUES (100,1,1,1,1,'profile:old','superseded','timeout_cancelled','2026-11-18 01:00:00')`,
		"INSERT INTO " + publishTgJobTable + ` (id,tenant_id,account_id,profile_id,channel_id,operation_no,status,send_phase,timeout_parent_job_id)
			VALUES (101,1,1,1,1,'profile:old','failed','timeout_wait_cleanup',100)`,
		"INSERT INTO " + publishProfileStateTable + " VALUES (1,1,1,'profile:old','pending',NULL)",
		"INSERT INTO hg_content_profile VALUES (1,1,'public',NULL)",
		"INSERT INTO " + publishChannelTable + " VALUES (1,1,1,NULL)",
		"INSERT INTO " + publishTgOutboxTable + ` (id,job_id,event_type,status,attempt_count,available_at)
			VALUES (100,100,'telegram_job.publish','delivered',0,LOCALTIMESTAMP),
			       (101,101,'telegram_job.publish','pending',0,LOCALTIMESTAMP)`,
		"UPDATE " + publishTgOutboxTable + " SET dedupe_key='telegram-job:'||job_id||':initial'",
	} {
		if _, err := db.Exec(ctx, query); err != nil {
			t.Fatal(err)
		}
	}
	var parent telegramJobRecord
	if err := db.Model(publishTgJobTable).Where("id", 100).Scan(&parent); err != nil {
		t.Fatal(err)
	}
	return parent
}

func TestTelegramTimeoutFinishEligibilityPostgres(t *testing.T) {
	for _, tc := range []struct {
		name      string
		change    string
		want      JobStatus
		wantError bool
		nilToken  bool
	}{
		{"eligible", "", JobStatusPending, false, false},
		{"other active same unique scope", "INSERT INTO " + publishTgJobTable + " (id,tenant_id,account_id,profile_id,channel_id,operation_no,status) VALUES (200,9,9,1,1,'profile:new','pending')", JobStatusSuperseded, false, false},
		{"new operation", "UPDATE " + publishProfileStateTable + " SET publish_operation_no='profile:new'", JobStatusSuperseded, false, false},
		{"cancel tombstone", "INSERT INTO " + publishProfileCancelTable + " VALUES (1,1,1,'profile:old')", JobStatusSuperseded, false, false},
		{"cancel state", "UPDATE " + publishProfileStateTable + " SET publish_task_status='canceling'", JobStatusSuperseded, false, false},
		{"delete fence", "INSERT INTO " + profileDeleteIntentTable + " VALUES (1,1)", JobStatusSuperseded, false, false},
		{"profile offline", "UPDATE hg_content_profile SET status=2", JobStatusSuperseded, false, false},
		{"channel disabled", "UPDATE " + publishChannelTable + " SET status=2", JobStatusSuperseded, false, false},
		{"tail identity changed", "UPDATE " + publishTgJobTable + " SET account_id=2 WHERE id=101", JobStatusFailed, true, false},
		{"tail belongs to another tenant", "UPDATE " + publishTgJobTable + " SET tenant_id=9 WHERE id=101", JobStatusFailed, true, false},
		{"nil token cannot activate", "", JobStatusSuperseded, false, true},
		{"nil token still gates messages", "INSERT INTO " + publishTgMessageTable + " VALUES (100,'sent',42)", JobStatusFailed, true, true},
		{"nil token still gates attempts", "INSERT INTO " + publishTgAttemptTable + " VALUES (1,100,'superseded',0,0,'')", JobStatusFailed, true, true},
		{"nil token still gates audit", "INSERT INTO " + publishTgAttemptTable + " VALUES (1,100,'superseded',1,1,''); INSERT INTO " + publishTgAttemptMessageTable + " VALUES (1,42)", JobStatusFailed, true, true},
		{"changed generation token", "UPDATE " + publishTgJobTable + " SET timeout_cleanup_at='2026-11-18 02:00:00' WHERE id=100", JobStatusFailed, false, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv("YOUBAN_PUBLISH_PROFILE_CANCEL_ENABLED", "true")
			db := telegramTimeoutFinishLocalDB(t)
			ctx := context.Background()
			parent := telegramTimeoutFinishSeed(t, db)
			if tc.nilToken {
				if _, err := db.Exec(ctx, "UPDATE "+publishTgJobTable+" SET timeout_cleanup_at=NULL WHERE id=100"); err != nil {
					t.Fatal(err)
				}
				parent.TimeoutCleanupAt = nil
			}
			if tc.change != "" {
				if _, err := db.Exec(ctx, tc.change); err != nil {
					t.Fatal(err)
				}
			}
			err := new(sSysPublish).finishTelegramSendTimeoutCleanup(ctx, parent)
			if (err != nil) != tc.wantError {
				t.Fatalf("err=%v wantError=%v", err, tc.wantError)
			}
			tail, err := db.GetOne(ctx, "SELECT status,dispatch_status,send_phase FROM "+publishTgJobTable+" WHERE id=101")
			if err != nil || tail["status"].String() != tc.want.String() {
				t.Fatalf("tail=%v want=%s err=%v", tail, tc.want, err)
			}
			if tc.want == JobStatusSuperseded {
				if tail["dispatch_status"].String() != DispatchStatusDone.String() || tail["send_phase"].String() != "" {
					t.Fatalf("retired tail still scheduled: %v", tail)
				}
				outbox, err := db.GetValue(ctx, "SELECT status FROM "+publishTgOutboxTable+" WHERE job_id=101")
				if err != nil || outbox.String() != telegramOutboxDelivered {
					t.Fatalf("tail outbox=%v err=%v", outbox, err)
				}
			}
			active, err := db.GetValue(ctx, "SELECT status FROM "+publishTgJobTable+" WHERE id=200")
			if err != nil || (!active.IsNil() && active.String() != "pending") {
				t.Fatalf("existing active was changed: %v %v", active, err)
			}
			cleanup, err := db.GetValue(ctx, "SELECT timeout_cleanup_at FROM "+publishTgJobTable+" WHERE id=100")
			if err != nil {
				t.Fatal(err)
			}
			if tc.want != JobStatusFailed && !cleanup.IsNil() {
				t.Fatal("safe cleanup did not settle parent token")
			}
			if tc.wantError && !tc.nilToken && cleanup.IsNil() {
				t.Fatal("unsafe cleanup cleared parent token")
			}
		})
	}
}

func TestTelegramTimeoutActiveConflictClassifier(t *testing.T) {
	for _, tc := range []struct {
		code       pq.ErrorCode
		constraint string
		want       bool
	}{
		{"23505", "uk_ybp_tg_job_active_profile_channel", true},
		{"23505", "another_unique_index", false},
		{"23503", "uk_ybp_tg_job_active_profile_channel", false},
	} {
		err := gerror.Wrap(&pq.Error{Code: tc.code, Constraint: tc.constraint}, "transition failed")
		if telegramTimeoutActiveConflict(err) != tc.want {
			t.Fatalf("code=%s constraint=%s", tc.code, tc.constraint)
		}
	}
	if telegramTimeoutActiveConflict(errors.New("23505 uk_ybp_tg_job_active_profile_channel")) {
		t.Fatal("plain text must not trigger a PostgreSQL unique-conflict retry")
	}
}

func TestTelegramTimeoutConflictRetriesAfterRollbackPostgres(t *testing.T) {
	t.Setenv("YOUBAN_PUBLISH_PROFILE_CANCEL_ENABLED", "true")
	db := telegramTimeoutFinishLocalDB(t)
	parent := telegramTimeoutFinishSeed(t, db)
	ctx := context.Background()
	// nextval is not rolled back. The first UPDATE simulates the exact index
	// race; only a new transaction can perform the second attempt successfully.
	for _, query := range []string{
		"CREATE SEQUENCE timeout_activation_attempt",
		`CREATE FUNCTION timeout_activation_race() RETURNS trigger LANGUAGE plpgsql AS $$
		BEGIN
			IF NEW.id=101 AND NEW.status='pending' AND OLD.status='failed' THEN
				IF nextval('timeout_activation_attempt')=1 THEN
					RAISE EXCEPTION 'simulated active index race'
						USING ERRCODE='23505',CONSTRAINT='uk_ybp_tg_job_active_profile_channel';
				END IF;
			END IF;
			RETURN NEW;
		END $$`,
		"CREATE TRIGGER timeout_activation_race BEFORE UPDATE ON " + publishTgJobTable + " FOR EACH ROW EXECUTE FUNCTION timeout_activation_race()",
	} {
		if _, err := db.Exec(ctx, query); err != nil {
			t.Fatal(err)
		}
	}
	if err := new(sSysPublish).finishTelegramSendTimeoutCleanup(ctx, parent); err != nil {
		t.Fatal(err)
	}
	attempts, err := db.GetValue(ctx, "SELECT last_value FROM timeout_activation_attempt")
	if err != nil || attempts.Int() != 2 {
		t.Fatalf("activation attempts=%v err=%v", attempts, err)
	}
	status, err := db.GetValue(ctx, "SELECT status FROM "+publishTgJobTable+" WHERE id=101")
	if err != nil || status.String() != JobStatusPending.String() {
		t.Fatalf("retry did not activate tail: %v %v", status, err)
	}
}
